/* Hide every symbol defined by this executable.
 *
 * Tectonic's semi-static link copies ICU, HarfBuzz, FreeType, Fontconfig,
 * expat, zlib, brotli, and (before the tectonic_dep_support patch) GLib into
 * the binary. Rust passes --export-dynamic, so those C symbols become
 * interposers: GTK, Mesa, and WebKit call our copies instead of the system
 * libraries. That is a SIGSEGV in g_bus_get_sync on GLib 2.84 (Debian 13) and
 * "free(): invalid pointer" from XML_ParserFree / g_string_free on Ubuntu 24.04.
 *
 * Copy-relocated libc data symbols must stay global or libc itself breaks.
 */
{
  global:
    stderr;
    stdin;
    stdout;
    timezone;
    __timezone;
    tzname;
    __tzname;
  local:
    *;
};
